CREATE TABLE "public"."booking_addons" (
  "id"                 bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "booking_id"         bigint                   NOT NULL,
  "addon_inventory_id" bigint                   NOT NULL,
  "quantity"           bigint                   NOT NULL,
  "created_at"         timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at"         timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  CONSTRAINT "booking_addons_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."booking_addons"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."booking_court_time" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."booking_court_timeslot_id_seq") NOT NULL,
  "court_id"   bigint                   NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "start_time" time without time zone   NOT NULL,
  "booking_id" bigint                   NOT NULL,
  CONSTRAINT "booking_court_timeslot_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."booking_court_time"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."booking" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "customer_id"  uuid,
  "created_at"   timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at"   timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "booking_date" date                     NOT NULL,
  CONSTRAINT "booking_booking_date_check" CHECK ((booking_date > now())),
  CONSTRAINT "booking_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."booking"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."branches" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "branch_name"     text,
  "tenant_id"       bigint,
  "created_at"      timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "branch_location" json                     NOT NULL,
  "layout_image"    text,
  "location"        jsonb,
  "contact_number"  text,
  "email"           text,
  CONSTRAINT "branches_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."branches"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."courts" (
  "id"           bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "branch_id"    bigint,
  "court_name"   text,
  "price"        real                     DEFAULT '0'::real,
  "created_at"   timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_st"   timestamp with time zone DEFAULT (now() AT TIME ZONE 'utc'::text),
  "opening_time" time without time zone,
  "closing_time" time without time zone,
  "sport_id"     bigint,
  CONSTRAINT "courts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."courts"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."employees" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"    uuid                     NOT NULL,
  "tenant_id"  bigint                   NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  CONSTRAINT "employees_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."employees"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."inventory_items" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "branch_id"   bigint                   NOT NULL,
  "description" text,
  "item_name"   text                     NOT NULL,
  "price"       real,
  "quantity"    bigint                   NOT NULL DEFAULT '0'::bigint,
  "item_image"  text,
  "is_listed"   boolean                  NOT NULL DEFAULT true,
  "created_at"  timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at"  timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  CONSTRAINT "inventory_items_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."inventory_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."sports" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "sport_name" text                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at" timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  CONSTRAINT "sports_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."sports"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."tenants" (
  "id"                  bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "business_name"       text                     NOT NULL DEFAULT ''::text,
  "company_str"         text                     NOT NULL DEFAULT ''::text,
  "created_at"          timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "updated_at"          timestamp with time zone NOT NULL DEFAULT (now() AT TIME ZONE 'utc'::text),
  "paymongo_account_id" text,
  "paymongo_link_id"    text,
  "onboarding_status"   boolean                  NOT NULL DEFAULT false,
  "payout_status"       boolean                  NOT NULL DEFAULT false,
  "contact_number"      text,
  "email"               text,
  CONSTRAINT "tenants_company_str_key" UNIQUE (company_str),
  CONSTRAINT "tenants_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."tenants"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."booking"
  ADD CONSTRAINT "booking_customer_id_fkey" FOREIGN KEY (customer_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."booking_addons"
  ADD CONSTRAINT "booking_addons_booking_id_fkey" FOREIGN KEY (booking_id) REFERENCES public.booking(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."booking_court_time"
  ADD CONSTRAINT "booking_court_booking_id_fkey" FOREIGN KEY (booking_id) REFERENCES public.booking(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."courts"
  ADD CONSTRAINT "courts_branch_id_fkey" FOREIGN KEY (branch_id) REFERENCES public.branches(id) ON UPDATE CASCADE ON DELETE CASCADE;

