  ADD CONSTRAINT "booking_court_timeslot_court_id_fkey" FOREIGN KEY (court_id) REFERENCES public.courts(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."employees"
  ADD CONSTRAINT "employees_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."inventory_items"
  ADD CONSTRAINT "inventory_items_branch_id_fkey" FOREIGN KEY (branch_id) REFERENCES public.branches(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."booking_addons"
  ADD CONSTRAINT "booking_addons_addon_inventory_id_fkey" FOREIGN KEY (addon_inventory_id) REFERENCES public.inventory_items(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."courts"
  ADD CONSTRAINT "courts_sport_id_fkey" FOREIGN KEY (sport_id) REFERENCES public.sports(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."branches"
  ADD CONSTRAINT "branches_tenant_id_fkey" FOREIGN KEY (tenant_id) REFERENCES public.tenants(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."employees"
  ADD CONSTRAINT "employees_tenant_id_fkey" FOREIGN KEY (tenant_id) REFERENCES public.tenants(id);

